import { requestComputerActionTurn } from "@katalon-experiments/ai-client/agents";
import { requestProvider } from "./provider.mjs";

export function hasPendingComputerSafetyCheck(item) {
  return (
    item?.type === "computer_call" &&
    Boolean(item.pending_safety_checks?.length)
  );
}

export function requestBrowserAction(options) {
  return requestComputerActionTurn({
    request: options.request,
    signal: options.signal,
    dispatch: () =>
      requestProvider({
        ...options,
        // The SDK cannot decode this reply and the host has applied none of its
        // actions. Request a replacement from the same last valid observations.
        // Share the transport's allowance; never restart the browser action loop.
        retryResponseReason: (body) =>
          body?.status === "completed" &&
          Array.isArray(body.output) &&
          !body.output.some(hasPendingComputerSafetyCheck) &&
          body.output.some(
            (item) =>
              item?.type === "computer_call" &&
              !Object.hasOwn(item, "action") &&
              (!Object.hasOwn(item, "actions") ||
                (Array.isArray(item.actions) && item.actions.length === 0)),
          )
            ? "Computer call has no action or actions"
            : undefined,
      }),
    isTerminal: (output) => output.some(hasPendingComputerSafetyCheck),
  });
}
